// The Compare screen against a scripted backend that serves real `weightlab diff` reports (fixtures/*.json,
// generated by the backend from the bundled fixture checkpoints).
import { act, render, screen, waitFor, within } from "@testing-library/react";
import userEvent from "@testing-library/user-event";
import { describe, expect, it, vi } from "vitest";
import type { ChangeReport, Comparison, ComparisonReport, TensorRow } from "../../lib/api/compare";
import type { Job, Model } from "../../lib/api/types";
import { apiError, fakeApi, json, withToken, type Call } from "../../test/fakeApi";
import { CompareView } from "./CompareView";
import gridJson from "./fixtures/report_grid.json";
import sJson from "./fixtures/report_s.json";
import vJson from "./fixtures/report_v.json";

const V = vJson as unknown as ChangeReport;
const S = sJson as unknown as ChangeReport;
const G = gridJson as unknown as ChangeReport;
const MODELS: Model[] = [
  { id: "mod_a", project_id: "prj_1", display_name: "base.safetensors", format: "safetensors", status: "ready", tensor_count: 9, fingerprint_method: "size_mtime" },
  { id: "mod_b", project_id: "prj_1", display_name: "ft.safetensors", format: "safetensors", status: "ready", tensor_count: 9, fingerprint_method: "size_mtime" },
];
const T0 = "2026-11-11T10:00:00Z";

function comparison(r: ChangeReport, extra: Partial<Comparison> = {}): Comparison {
  return {
    id: "cmp_1",
    project_id: "prj_1",
    model_a_id: "mod_a",
    model_b_id: "mod_b",
    lineage: r.compatibility.lineage,
    counts: r.compatibility.counts,
    policy: r.compatibility.lineage.compatibility_class === "V" ? "strict" : "descriptive_only",
    report: null,
    latest_report_job_id: null,
    created_at: T0,
    ...extra,
  };
}

function stored(r: ChangeReport, job = "job_1", status: Partial<ComparisonReport["current_model_status"]> = {}): ComparisonReport {
  return {
    comparison_id: "cmp_1",
    job_id: job,
    complete: r.complete,
    consistency: "best_effort",
    created_at: T0,
    current_model_status: { model_a: "ready", model_b: "ready", ...status },
    report: r,
  };
}

const job = (state: Job["state"], extra: Partial<Job> = {}): Job => ({
  job_id: "job_1",
  kind: "comparison_report",
  state,
  progress: state === "completed" ? 1 : 0.4,
  poll_after_ms: 100,
  estimated_bytes: 1_000_000,
  bytes_scanned: 400_000,
  created_at: T0,
  ...extra,
});

/** A mutable backend: tests change `state` between requests. */
function backend(state: { cmp: Comparison; report?: ComparisonReport; jobs: Record<string, Job>; onSubmit?: (c: Call) => Response; settings?: object }) {
  return fakeApi((c) => {
    const k = `${c.method} ${c.url.pathname}`;
    if (k === "GET /api/v1/projects/prj_1/comparisons") return json([state.cmp]);
    if (k === `GET /api/v1/comparisons/${state.cmp.id}`) return json(state.cmp);
    if (k === `GET /api/v1/comparisons/${state.cmp.id}/report`) return state.report ? json(state.report) : apiError(404, "NOT_FOUND", "no report");
    if (k === "GET /api/v1/settings") return json(state.settings ?? { memory_budget_mib: 1024, max_job_seconds: 600, max_threads: 2 });
    if (k === "POST /api/v1/jobs") {
      if (state.onSubmit) return state.onSubmit(c);
      throw new Error("unexpected submit");
    }
    const m = /^(GET|POST) \/api\/v1\/jobs\/([^/]+)(\/cancel)?$/.exec(k);
    if (m && state.jobs[m[2]!]) return json(state.jobs[m[2]!]);
    throw new Error(`unexpected request ${k}`);
  });
}

function view(onInspect = vi.fn()) {
  withToken();
  const models = { data: MODELS, error: undefined, loading: false, reload: () => {} };
  render(<CompareView projectId="prj_1" projectName="Research" models={models} onGoWorkspace={() => {}} onInspect={onInspect} />);
  return onInspect;
}

const rows = () => within(screen.getByRole("tabpanel", { name: /Tensors/ })).getAllByRole("row").slice(1);

describe("Compare: header and completeness", () => {
  it("complete Class V report: orientation, class, consistency, complete badge, causal caveat", async () => {
    backend({ cmp: comparison(V, { report: { job_id: "job_1", complete: true, consistency: "best_effort", created_at: T0 } }), report: stored(V), jobs: {} });
    view();
    expect(await screen.findByText("B − A")).toBeInTheDocument();
    expect(await screen.findByText("Complete")).toBeInTheDocument();
    expect(screen.getAllByTitle(/Class V/)[0]).toHaveTextContent("V");
    expect(screen.getByText(/do not show that the derived model is more accurate/)).toBeInTheDocument();
    expect(screen.queryByRole("note", { name: /Incomplete report/ })).toBeNull();
    expect(screen.getByText(/best effort \(quick fingerprints\)/)).toBeInTheDocument();
  });

  it("incomplete Class S report: prominent class warning, incomplete notice, withheld values labelled", async () => {
    backend({ cmp: comparison(S, { report: { job_id: "job_1", complete: false, consistency: "best_effort", created_at: T0 } }), report: stored(S), jobs: {} });
    view();
    const warn = await screen.findByRole("note", { name: /Class S/ });
    expect(warn).toHaveTextContent(/element-wise differences may be meaningless/);
    expect(await screen.findByRole("note", { name: "Incomplete report" })).toHaveTextContent(/not a complete comparison/);
    expect(screen.getByText("Incomplete")).toBeInTheDocument();
    expect(screen.queryByText("Complete")).toBeNull();
    const f64 = rows().find((r) => within(r).queryByText("p.f64"))!;
    // relative_l2, delta_l2, delta_rms and max_abs_delta are withheld; cosine (0 here) is a real value.
    const f64Row = S.tensors.find((t) => t.key === "p.f64")!;
    expect(within(f64).getAllByText("withheld")).toHaveLength(4);
    expect(f64Row.withheld_metrics).toEqual(expect.arrayContaining(["relative_l2", "delta_l2", "delta_rms", "max_abs_delta"]));
    expect(within(f64).getByTitle(String(f64Row.metrics.cosine.value))).toBeInTheDocument();
  });

  it("warns when files changed after the report (snapshot freshness)", async () => {
    backend({ cmp: comparison(V, { report: { job_id: "job_1", complete: true, consistency: "best_effort", created_at: T0 } }), report: stored(V, "job_1", { model_b: "changed" }), jobs: {} });
    view();
    expect(await screen.findByRole("note", { name: "Files changed since the report" })).toHaveTextContent(/snapshot/);
  });
});

describe("Compare: grid, rankings and drill-down", () => {
  function withGrid() {
    backend({ cmp: comparison(G, { report: { job_id: "job_1", complete: true, consistency: "verified", created_at: T0 } }), report: stored(G), jobs: {} });
    return view();
  }

  it("grid shows layers, the unlayered row and other roles; a cell filters the tensor ranking", async () => {
    const user = userEvent.setup();
    withGrid();
    const grid = await screen.findByRole("grid", { name: /Relative L2 by layer and role/ });
    expect(within(grid).getByRole("rowheader", { name: "No layer" })).toBeInTheDocument();
    expect(within(grid).getByRole("columnheader", { name: "other" })).toBeInTheDocument();
    const cell = within(grid).getByRole("gridcell", { name: /Layer 1, attention\.q: Relative L2 .*, 2 tensors/ });
    await user.click(cell);
    expect(cell).toHaveAttribute("aria-selected", "true");
    expect(rows().map((r) => within(r).getAllByRole("button")[0]!.textContent).sort()).toEqual([
      "model.layers.1.self_attn.q_proj.bias",
      "model.layers.1.self_attn.q_proj.weight",
    ]);
    await user.click(screen.getByRole("button", { name: /Clear filter/ }));
    expect(rows()).toHaveLength(G.tensors.length);
  });

  it("grid is keyboard operable: arrows move, Enter filters", async () => {
    const user = userEvent.setup();
    withGrid();
    const grid = await screen.findByRole("grid");
    const first = within(grid).getAllByRole("gridcell")[0]!;
    first.focus();
    await user.keyboard("{ArrowRight}");
    const second = within(grid).getAllByRole("gridcell")[1]!;
    expect(second).toHaveFocus();
    await user.keyboard("{ArrowDown}{Enter}");
    await waitFor(() => expect(screen.getByRole("status", { name: "" })).toBeTruthy());
    expect(screen.getByText(/^Showing/)).toBeInTheDocument();
  });

  it("cosine of a multi-tensor cell is n/a, not a number", async () => {
    const user = userEvent.setup();
    withGrid();
    await user.selectOptions(await screen.findByLabelText("Metric"), "cosine");
    const grid = screen.getByRole("grid", { name: /Cosine similarity by layer and role/ });
    expect(within(grid).getByRole("gridcell", { name: /Layer 0, attention\.q: .*Not defined for several tensors/ })).toHaveTextContent("n/a");
  });

  it("rankings sort by the selected metric and by name; ties and unavailable values are deterministic", async () => {
    const user = userEvent.setup();
    withGrid();
    await screen.findByRole("grid");
    const names = () => rows().map((r) => within(r).getAllByRole("button")[0]!.textContent);
    const byRel = [...G.tensors]
      .sort((a, b) => (b.metrics.relative_l2.value as number) - (a.metrics.relative_l2.value as number) || a.key.localeCompare(b.key))
      .map((t) => t.key);
    expect(names()).toEqual(byRel);
    await user.click(screen.getByRole("button", { name: /^Tensor/ }));
    expect(names()).toEqual([...G.tensors.map((t) => t.key)].sort((a, b) => a.localeCompare(b, "en", { numeric: true })).reverse());
  });

  it("layer and role rankings show the report's own rollups and drill into tensors", async () => {
    const user = userEvent.setup();
    withGrid();
    await screen.findByRole("grid");
    await user.click(screen.getByRole("tab", { name: /Layers/ }));
    const panel = screen.getByRole("tabpanel", { name: /Layers/ });
    const l2 = G.layers.find((l) => l.layer === 2)!;
    const row = within(panel).getByRole("button", { name: "Layer 2" }).closest("tr")!;
    expect(within(row).getAllByTitle(String(l2.relative_l2)).length).toBeGreaterThan(0);
    await user.click(within(panel).getByRole("button", { name: "Layer 2" }));
    expect(rows().every((r) => /layers\.2\./.test(within(r).getAllByRole("button")[0]!.textContent ?? ""))).toBe(true);
  });

  it("drill-down shows metrics and counts, opens the tensor in A, and never offers a delta heatmap", async () => {
    const user = userEvent.setup();
    const t: TensorRow = G.tensors.find((x) => x.key === "model.layers.0.mlp.down_proj.weight")!;
    const onInspect = vi.fn();
    backend({ cmp: comparison(G, { report: { job_id: "job_1", complete: true, consistency: "verified", created_at: T0 } }), report: stored(G), jobs: {} });
    const calls = fakeApi((c) => {
      const k = `${c.method} ${c.url.pathname}`;
      if (k === "GET /api/v1/models/mod_a/tensors") return json({ total: 1, items: [{ id: "tns_down", raw_key: t.key }] });
      if (k === "GET /api/v1/projects/prj_1/comparisons") return json([comparison(G, { report: { job_id: "job_1", complete: true, consistency: "verified", created_at: T0 } })]);
      if (k === "GET /api/v1/comparisons/cmp_1") return json(comparison(G, { report: { job_id: "job_1", complete: true, consistency: "verified", created_at: T0 } }));
      if (k === "GET /api/v1/comparisons/cmp_1/report") return json(stored(G));
      if (k === "GET /api/v1/settings") return json({});
      throw new Error(k);
    });
    view(onInspect);
    await user.click(await screen.findByRole("button", { name: t.key }));
    const detail = screen.getByRole("region", { name: t.key });
    expect(within(detail).getByText(String(t.metrics.relative_l2.value))).toBeInTheDocument();
    expect(within(detail).getByText("mlp.down")).toBeInTheDocument();
    expect(within(detail).getByRole("button", { name: /Delta heatmap/ })).toBeDisabled();
    expect(within(detail).getByText(/Not available yet/)).toBeInTheDocument();
    await user.click(within(detail).getByRole("button", { name: /Inspect in A/ }));
    await waitFor(() => expect(onInspect).toHaveBeenCalledWith("mod_a", "tns_down"));
    expect(calls.find((c) => c.url.pathname.endsWith("/tensors"))!.url.searchParams.get("q")).toBe(t.key);
  });
});

describe("Compare: analysis job lifecycle", () => {
  it("runs, polls and shows the report only after the job completed", async () => {
    const user = userEvent.setup();
    const state = { cmp: comparison(V), report: undefined as ComparisonReport | undefined, jobs: {} as Record<string, Job>, onSubmit: undefined as ((c: Call) => Response) | undefined };
    let polls = 0;
    state.onSubmit = (c) => {
      expect(c.body).toMatchObject({ kind: "comparison_report", comparison_id: "cmp_1", consistency: "verified" });
      state.jobs.job_1 = job("running");
      state.cmp = { ...state.cmp, latest_report_job_id: "job_1" };
      return json(job("queued"), 202);
    };
    fakeApi((c) => {
      const k = `${c.method} ${c.url.pathname}`;
      if (k === "GET /api/v1/jobs/job_1") {
        polls += 1;
        if (polls >= 2) {
          state.jobs.job_1 = job("completed", { result: { kind: "comparison_report", comparison_id: "cmp_1", complete: true, published: true } as never });
          state.report = stored(V);
          state.cmp = { ...state.cmp, report: { job_id: "job_1", complete: true, consistency: "verified", created_at: T0 } };
        }
        return json(state.jobs.job_1);
      }
      if (k === "POST /api/v1/jobs") return state.onSubmit!(c);
      if (k === "GET /api/v1/projects/prj_1/comparisons") return json([state.cmp]);
      if (k === "GET /api/v1/comparisons/cmp_1") return json(state.cmp);
      if (k === "GET /api/v1/comparisons/cmp_1/report") return state.report ? json(state.report) : apiError(404, "NOT_FOUND", "none");
      if (k === "GET /api/v1/settings") return json({ memory_budget_mib: 2048, max_job_seconds: 900 });
      throw new Error(k);
    });
    view();
    expect(await screen.findByText(/No report yet/)).toBeInTheDocument();
    await user.click(screen.getByRole("radio", { name: /Verified/ }));
    await user.click(screen.getByRole("button", { name: "Run analysis" }));
    expect(await screen.findByRole("progressbar", { name: "Analysis progress" })).toBeInTheDocument();
    expect(screen.queryByRole("grid")).toBeNull(); // nothing before completion
    expect(await screen.findByRole("grid", {}, { timeout: 5000 })).toBeInTheDocument();
    expect(screen.getByRole("button", { name: "Re-run analysis" })).toBeInTheDocument();
  });

  it("a delayed canceled-job lookup cannot replace a newer retry", async () => {
    const user = userEvent.setup();
    const canceled = job("canceled", { job_id: "job_old", created_at: "2026-11-11T10:00:00.000Z" });
    const newRunning = job("running", { job_id: "job_new", created_at: "2026-11-11T10:00:01.000Z", poll_after_ms: 600 });
    const state = {
      cmp: comparison(V),
      report: undefined as ComparisonReport | undefined,
    };
    let submitCount = 0;
    let resolveStale!: (response: Response) => void;
    let oldLookup = false;
    const stale = new Promise<Response>((resolve) => { resolveStale = resolve; });
    fakeApi((c) => {
      const k = `${c.method} ${c.url.pathname}`;
      if (k === "GET /api/v1/projects/prj_1/comparisons") return json([state.cmp]);
      if (k === "GET /api/v1/comparisons/cmp_1") return json(state.cmp);
      if (k === "GET /api/v1/comparisons/cmp_1/report") return state.report ? json(state.report) : apiError(404, "NOT_FOUND", "none");
      if (k === "GET /api/v1/settings") return json({ memory_budget_mib: 1024, max_job_seconds: 600 });
      if (k === "POST /api/v1/jobs") {
        submitCount++;
        const first = submitCount === 1;
        state.cmp = { ...state.cmp, latest_report_job_id: first ? "job_old" : "job_new" };
        return json(first ? job("running", { job_id: "job_old", created_at: canceled.created_at }) : newRunning, 202);
      }
      if (k === "POST /api/v1/jobs/job_old/cancel") return json(canceled);
      if (k === "GET /api/v1/jobs/job_old") {
        oldLookup = true;
        return stale; // the old latest-job lookup is delayed until after the retry
      }
      if (k === "GET /api/v1/jobs/job_new") {
        state.report = stored(V, "job_new");
        state.cmp = { ...state.cmp, report: { job_id: "job_new", complete: true, consistency: "best_effort", created_at: T0 } };
        return json(job("completed", {
          job_id: "job_new", created_at: newRunning.created_at,
          result: { kind: "comparison_report", comparison_id: "cmp_1", complete: true, published: true } as never,
        }));
      }
      throw new Error(k);
    });
    view();
    await user.click(await screen.findByRole("button", { name: "Run analysis" }));
    expect(await screen.findByRole("progressbar")).toBeInTheDocument();
    await user.click(screen.getByRole("button", { name: "Cancel analysis" }));
    expect(await screen.findByRole("alert")).toHaveTextContent(/canceled/);
    await waitFor(() => expect(oldLookup).toBe(true));
    await user.click(screen.getByRole("button", { name: "Run analysis" }));
    expect(await screen.findByRole("progressbar")).toBeInTheDocument();
    await act(async () => { resolveStale(json(canceled)); });
    // The stale GET returns *after* the new POST. It may not switch the UI back to canceled.
    expect(screen.getByRole("progressbar")).toBeInTheDocument();
    expect(screen.queryByRole("alert")).toBeNull();
    expect(await screen.findByRole("grid", {}, { timeout: 5000 })).toBeInTheDocument();
    expect(submitCount).toBe(2);
  });

  it("after a refresh, rediscovers a running job and cancels it; the previous report stays", async () => {
    const user = userEvent.setup();
    const state = {
      cmp: comparison(V, { latest_report_job_id: "job_2", report: { job_id: "job_1", complete: true, consistency: "best_effort", created_at: T0 } }),
      report: stored(V),
      jobs: { job_2: job("running", { job_id: "job_2" }) } as Record<string, Job>,
    };
    fakeApi((c) => {
      const k = `${c.method} ${c.url.pathname}`;
      if (k === "POST /api/v1/jobs/job_2/cancel") {
        state.jobs.job_2 = job("canceled", { job_id: "job_2" });
        return json(state.jobs.job_2);
      }
      if (k === "GET /api/v1/jobs/job_2") return json(state.jobs.job_2);
      if (k === "GET /api/v1/projects/prj_1/comparisons") return json([state.cmp]);
      if (k === "GET /api/v1/comparisons/cmp_1") return json(state.cmp);
      if (k === "GET /api/v1/comparisons/cmp_1/report") return json(state.report);
      if (k === "GET /api/v1/settings") return json({});
      throw new Error(k);
    });
    view();
    expect(await screen.findByRole("progressbar")).toBeInTheDocument();
    expect(await screen.findByRole("grid")).toBeInTheDocument(); // the stored report is shown meanwhile
    await user.click(screen.getByRole("button", { name: "Cancel analysis" }));
    const alert = await screen.findByRole("alert");
    expect(alert).toHaveTextContent(/canceled/);
    expect(alert).toHaveTextContent(/previous successful one/);
    expect(screen.getByRole("grid")).toBeInTheDocument();
    expect(screen.getByRole("button", { name: "Re-run analysis" })).toBeInTheDocument(); // retry
  });

  it("a failed run explains FILE_CHANGED and keeps the previous report", async () => {
    const failed = job("failed", { job_id: "job_3", error: { code: "FILE_CHANGED", message: "ft.safetensors changed", retryable: false } });
    backend({
      cmp: comparison(V, { latest_report_job_id: "job_3", report: { job_id: "job_1", complete: true, consistency: "best_effort", created_at: T0 } }),
      report: stored(V),
      jobs: { job_3: failed },
    });
    view();
    const alert = await screen.findByRole("alert");
    expect(alert).toHaveTextContent("The last analysis failed");
    expect(alert).toHaveTextContent(/Re-import the changed model/);
    expect(alert).toHaveTextContent(/Nothing from that run was published/);
    expect(await screen.findByRole("grid")).toBeInTheDocument();
  });

  it.each([
    ["CONFLICT", 409, /Create a new comparison/],
    ["LINEAGE_UNVERIFIED", 409, /acknowledge that the numbers describe raw/],
    ["RESOURCE_LIMIT", 422, /memory_budget_mib/],
  ])("submit refused with %s shows its resolution", async (code, status, advice) => {
    const user = userEvent.setup();
    backend({ cmp: comparison(V), jobs: {}, onSubmit: () => apiError(status, code, `refused: ${code}`) });
    view();
    await user.click(await screen.findByRole("button", { name: "Run analysis" }));
    expect(await screen.findByText(advice)).toBeInTheDocument();
    expect(screen.getByText(`refused: ${code}`)).toBeInTheDocument();
  });

  it("a deduplicated submission says it joined the running analysis", async () => {
    const user = userEvent.setup();
    backend({ cmp: comparison(V), jobs: { job_1: job("running") }, onSubmit: () => json(job("running", { deduplicated: true }), 202) });
    view();
    await user.click(await screen.findByRole("button", { name: "Run analysis" }));
    expect(await screen.findByText(/joined the analysis that was already running/)).toBeInTheDocument();
  });

  it("a superseded run says the later report is shown", async () => {
    backend({
      cmp: comparison(V, { latest_report_job_id: "job_4", report: { job_id: "job_5", complete: true, consistency: "verified", created_at: T0 } }),
      report: stored(V, "job_5"),
      jobs: { job_4: job("completed", { job_id: "job_4", result: { kind: "comparison_report", comparison_id: "cmp_1", complete: true, published: false } as never }) },
    });
    view();
    expect(await screen.findByText(/later-submitted run had already stored its report/)).toBeInTheDocument();
  });
});

describe("Compare: large reports", () => {
  it("renders a 20,000-tensor report with a bounded table (100 rows per page)", async () => {
    const base = G.tensors[0]!;
    const many: TensorRow[] = Array.from({ length: 20_000 }, (_, i) => ({
      ...base,
      key: `model.layers.${i % 80}.mlp.t${i}.weight`,
      layer: i % 80,
      role: ["mlp.up", "mlp.down", "attention.q", "norm"][i % 4]!,
      metrics: { ...base.metrics, relative_l2: { ...base.metrics.relative_l2, value: (i % 997) / 1000 } },
    }));
    const big = { ...G, tensors: many };
    backend({ cmp: comparison(G, { report: { job_id: "job_1", complete: true, consistency: "best_effort", created_at: T0 } }), report: stored(big as ChangeReport), jobs: {} });
    view();
    const grid = await screen.findByRole("grid", {}, { timeout: 10_000 });
    expect(within(grid).getAllByRole("row")).toHaveLength(81); // header + 80 layers
    expect(rows()).toHaveLength(100);
    expect(screen.getByText(/20,000 tensors · page 1 of 200/)).toBeInTheDocument();
  }, 30_000);
});
